<?php require 'includes/bootstrap.php'; require_login();if($_SERVER['REQUEST_METHOD']!=='POST'||!csrf_ok()){http_response_code(400);exit('Некорректный запрос.');}$pid=(int)($_POST['property_id']??0);$s=$pdo->prepare('SELECT id FROM favorites WHERE user_id=? AND property_id=?');$s->execute([user()['id'],$pid]);if($s->fetch()){$pdo->prepare('DELETE FROM favorites WHERE user_id=? AND property_id=?')->execute([user()['id'],$pid]);$_SESSION['flash']='Объект удалён из избранного.';}else{$pdo->prepare('INSERT IGNORE INTO favorites(user_id,property_id) VALUES(?,?)')->execute([user()['id'],$pid]);$_SESSION['flash']='Объект добавлен в избранное.';}header('Location: '.($_SERVER['HTTP_REFERER']??'favorites.php'));
